// NewSprintf returns a new String binding that formats one or more source bindings using the specified format string.
// The format string follows fmt.Sprintf conventions. Sources may be Bool, Float, Int, Rune, String, URI, or Untyped (Bytes) bindings.
//
// The resulting binding supports bidirectional updates:
//   - Get() formats the source values using fmt.Sprintf
//   - Set() parses the string using fmt.Sscanf and updates each source (except Bytes, which returns an error)
//
// Example:
//
//	firstName := binding.NewString()
//	lastName := binding.NewString()
//	fullName := binding.NewSprintf("%s %s", firstName, lastName)
//	firstName.Set("John")
//	lastName.Set("Doe")
//	// fullName.Get() returns "John Doe"
//	fullName.Set("Jane Smith")
//	// firstName.Get() returns "Jane", lastName.Get() returns "Smith"
//
// Since: 2.5
func NewSprintf(format string, sources ...DataItem) String {
	s := &sprintfBinding{
		format:  format,
		sources: sources,
	}

	// Setup listeners on all sources to trigger updates
	for _, source := range sources {
		source.AddListener(NewDataListener(func() {
			s.trigger()
		}))
	}

	return s
}

// stringToStringWithFormatBinding wraps a String binding with a format string
type stringToStringWithFormatBinding struct {
	base
	format string
	source String
}

// Get returns the formatted string value
func (s *stringToStringWithFormatBinding) Get() (string, error) {
	val, err := s.source.Get()
	if err != nil {
		return "", err
	}
	return fmt.Sprintf(s.format, val), nil
}

// Set parses the formatted string and updates the source
func (s *stringToStringWithFormatBinding) Set(str string) error {
	var val string
	n, err := fmt.Sscanf(str, s.format, &val)
	if err != nil {
		return fmt.Errorf("failed to parse string: %w", err)
	}
	if n != 1 {
		return fmt.Errorf("format matched %d values but expected 1", n)
	}
	return s.source.Set(val)
}

// StringToStringWithFormat returns a new String binding that formats a source String binding using the specified format.
// If the format is "%s" (identity), the original binding is returned directly without wrapping.
//
// Example:
//
//	name := binding.NewString()
//	name.Set("Alice")
//	greeting := binding.StringToStringWithFormat(name, "Hello, %s!")
//	// greeting.Get() returns "Hello, Alice!"
//
// Since: 2.5
func StringToStringWithFormat(source String, format string) String {
	// Optimization: return source directly for identity format
	if format == "%s" {
		return source
	}

	s := &stringToStringWithFormatBinding{
		format: format,
		source: source,
	}

	// Listen to source changes
	source.AddListener(NewDataListener(func() {
		s.trigger()
	}))

	return s
}

